sys_script_include.script:
var EventUtils = Class.create();
EventUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {


    isLocationAvailable: function() {
        var location = this.getParameter('sysparm_location');
        var eventDate = this.getParameter('sysparm_event_date');
        var gr = new GlideRecord('Event_Record');
        gr.addQuery('u_location', location);
        gr.addQuery('u_event_date', eventDate);
        gr.query();
        return gr.hasNext() ? 'false' : 'true';
    }

});

    type: 'EventUtils'
